(()=>{'use strict';
const C=window.LessonCore,D=window.LessonContent,$=s=>document.querySelector(s),esc=C.escape;
let state=C.initial(),saveError=false,selected=null,drag=null,undo=[],toastTimer;
try{const raw=localStorage.getItem(C.KEY);if(raw)state=C.restore(JSON.parse(raw));}catch(e){saveError=true;}
const teacher=new URLSearchParams(location.search).get('teacher')==='1';
const tr=(en,zh)=>esc(en)+(state.lang==='bi'&&zh?`<span class="zh" lang="zh-Hans">${esc(zh)}</span>`:'');
const pair=v=>tr(v[0],v[1]);
const button=(en,zh,act,cls='',extra='')=>`<button class="btn ${cls}" data-act="${act}" ${extra}>${tr(en,zh)}</button>`;
const field=(label,zh,path,kind='text',hint='',placeholder='')=>`<label class="field">${tr(label,zh)}${kind==='textarea'?`<textarea data-bind="${path}" placeholder="${esc(placeholder)}" rows="3">${esc(get(path))}</textarea>`:`<input type="${kind}" data-bind="${path}" value="${esc(get(path))}" placeholder="${esc(placeholder)}" maxlength="${path==='student.name'?90:path==='design.title'?100:600}">`}${hint?`<small>${hint}</small>`:''}</label>`;
const guide=(file,en='Open the visual guide',zh='打开图示指南')=>`<button class="guide-link" data-guide="${file}">${tr(en,zh)} ↗</button>`;
const shot=(file,caption,guideFile)=>`<figure class="shot"><img src="assets/screens/${file}" alt="${esc(caption)}" loading="lazy"><figcaption>${esc(caption)}</figcaption><button data-image="assets/screens/${file}" data-title="${esc(caption)}">${tr('Enlarge screenshot','放大截图')} ⤢</button></figure>${guideFile?guide(guideFile):''}`;
function get(path){return path.split('.').reduce((v,k)=>v?.[k],state)??'';}
function set(path,value){const keys=path.split('.');let o=state;keys.slice(0,-1).forEach(k=>o=o[k]);o[keys.at(-1)]=value;}
function save(){state.updated=new Date().toISOString();try{localStorage.setItem(C.KEY,JSON.stringify(state));saveError=false;}catch(e){saveError=true;}const el=$('#save-status');if(el)el.textContent=saveError?(state.lang==='bi'?'未能保存：请下载备份':'Not saved: download a backup'):(state.lang==='bi'?'已保存在此浏览器':'Saved in this browser');}
function toast(en,zh){const el=$('#toast');el.textContent=state.lang==='bi'&&zh?`${en} / ${zh}`:en;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',4500);}
function language(){return `<select class="language" id="language" aria-label="Language / 语言"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="bi" ${state.lang==='bi'?'selected':''}>English + 中文</option></select>`;}
function brand(){return `<div class="brand"><span class="brand-mark" aria-hidden="true">↗</span><span>CS with Mr Dave<small>Year 9 · Design studio</small></span></div>`;}
function landing(){return `<header class="topbar"><div class="wrap">${brand()}<div class="toolbar">${language()}${button('Glossary','词汇表','glossary','small quiet')}</div></div></header><main id="main" class="wrap"><section class="hero"><div><div class="eyebrow">Year 9 · App development · 60 minutes</div><h1>${tr('Your idea.','你的想法。')}<br><em>${tr('Your first app.','你的第一个应用。')}</em></h1><p class="lead">${tr('Design an app about something you want to share, explore, showcase or create. You choose the topic and the audience.','设计一个应用，分享、探索、展示或表达你感兴趣的内容。主题和目标用户由你决定。')}</p><div class="principles"><span>${tr('One first screen','一个初始界面')}</span><span>${tr('Two useful interactions','两个有用的互动')}</span><span>${tr('Your own choices','由你自己选择')}</span></div><p class="small muted">${tr('Today you will investigate and design. You will build your app in the practical lesson.','今天先研究和设计，实践课再制作应用。')}</p></div><div class="hero-panel"><div class="eyebrow">Your workspace, next step</div><img src="assets/guides/R2-designer-orientation.png" alt="A genuine MIT Neo Designer screenshot showing an empty project and labelled interface areas"><p>${tr('We will help you access MIT App Inventor and recognise its workspace. Your app idea stays yours.','我们会帮助你进入 MIT App Inventor 并认识工作区。应用的想法由你决定。')}</p></div></section><section class="entry-card"><h2 style="font-size:1.6rem">${tr(state.joined?'Continue your design journey':'Start your design journey',state.joined?'继续你的设计之旅':'开始你的设计之旅')}</h2><form id="entry-form"><div class="entry-grid">${field('Your name','姓名','student.name','text','','e.g. Sam')}${field('Class / form','班级','student.form','text','','e.g. 9T')}<label class="check"><input id="entry-guided" type="checkbox" ${state.guided?'checked':''}><span>${tr('One step at a time','一步一步完成')}<span class="small muted" style="display:block">${tr('Show extra prompts and sentence starters.','显示更多提示和句子开头。')}</span></span></label></div><div class="entry-actions"><button class="btn primary" type="submit">${tr(state.joined?'Continue my lesson':'Start my lesson',state.joined?'继续学习':'开始学习')} →</button>${state.joined?button('Start a new response','开始新的答卷','new-response','quiet'):''}<span class="small muted">${tr('Short phrases, labelled drawings and Mandarin notes are welcome.','可以使用短语、标注图和中文笔记。')}</span></div></form></section><div class="card tint"><div class="eyebrow">WAGBA</div><p style="margin:0">${pair(D.wagba)}</p></div><div class="goals-grid">${Object.entries(D.goals).map(([a,v])=>`<article class="goal-tile"><span class="letter">${a}</span><strong>${pair(D.areas[a])}</strong><p>${pair(v)}</p></article>`).join('')}</div>${teacher?teacherPanel():''}<p class="footer-note">${tr('Your responses save on this browser. At the end, save a PDF and submit it in Teams as directed.','答案会保存在此浏览器。最后保存 PDF，并按老师要求提交到 Teams。')}</p></main>`;}
function sidebar(){return `<aside class="sidebar" id="lesson-goals"><h2>WAGBA</h2><p class="wagba">${pair(D.wagba)}</p>${Object.entries(D.goals).map(([a,v])=>`<div class="goal"><strong>${pair(D.areas[a])}</strong>${pair(v)}</div>`).join('')}<nav class="side-nav" aria-label="Lesson stages">${C.stages.map((s,i)=>`<button class="stage-link ${state.stage===s[0]?'active':''} ${state.done.includes(s[0])?'done':''}" data-stage="${s[0]}" ${state.stage===s[0]?'aria-current="step"':''}><span class="nav-num">${state.done.includes(s[0])?'✓':i+1}</span><span>${tr(s[1],s[2])}</span></button>`).join('')}</nav><p class="small muted" style="margin:20px 10px 0">${tr('Suggested times help you pace your work.','建议时间帮助你安排进度。')}</p></aside>`;}
const intro={read:['Apps respond to people','应用会回应用户','Read the key ideas, then try four quick questions. You are free to choose your own appropriate app topic.','先阅读核心概念，再尝试四道小题。你可以自由选择适合学校的应用主题。'],starter:['Four things to notice','观察四个重点','Choose one answer for each question. Check the feedback before moving on.','每题选择一个答案。继续前先查看反馈。'],learning:['What will you improve today?','今天你要提高什么？','Use what you have just tried. Keep what you already know, and choose where to focus next.','根据刚刚的练习，确认已经掌握的内容，再选择今天的重点。'],setup:['Set up your MIT access','设置你的 MIT 账户访问','Follow the school-email route. Stop at the project list, then continue your design lesson.','使用学校邮箱。进入项目列表后就停止设置，继续本课设计活动。'],investigate:['Notice what an app does','观察应用如何工作','Study two actions in an app you know. Record exactly how the app responds.','研究一个熟悉应用中的两个操作，准确记录应用如何回应。'],reset:['A quick reset','轻松回顾','Three short questions. Use the feedback to get ready for your own design.','完成三道短题，利用反馈为自己的设计做准备。'],design:['Design your own app','设计你自己的应用','Work through these four steps. They all develop the same app idea.','按四个步骤进行。它们都是为了完善同一个应用想法。'],challenge:['Take your idea further','进一步完善你的想法','When your main design is complete, choose one useful next challenge.','完成主要设计后，选择一个有用的进一步挑战。'],pitstop:['Where is your learning now?','你现在的学习状态如何？','Choose a confidence phase for each area. They do not all have to be the same.','为每个领域选择学习状态。不同领域可以处于不同状态。'],finish:['Keep your design for the practical','为实践课保留你的设计','Explain one interaction, check your work, then save your PDF for Teams.','解释一个互动，检查作品，然后保存 PDF 以提交到 Teams。']};
function shell(){const i=C.stages.findIndex(s=>s[0]===state.stage),stage=C.stages[i],t=intro[state.stage];return `<header class="topbar"><div class="wrap">${brand()}<div class="toolbar"><span class="progress-label">${i+1} / 10</span><div class="progress-track" aria-hidden="true"><div style="width:${(i+1)*10}%"></div></div>${language()}${button('Words','词汇','glossary','small quiet')}${button('Guides','指南','resources','small quiet')}${button(state.student.name,'姓名','identity','small quiet')}</div></div></header>${saveError?`<div class="notice-error">${tr('This browser could not save the latest work. Download a backup before leaving.','此浏览器未能保存最新内容。离开前请下载备份。')}</div>`:''}<div class="layout" id="layout">${sidebar()}<main id="main" class="main"><button class="btn small mobile-goals" data-act="mobile-goals">${tr('WAGBA & lesson stages','学习目标与步骤')} ☰</button><header class="stage-header"><div class="row spread"><div class="eyebrow">${tr(stage[1],stage[2])}</div><span class="chip">${stage[3]} ${tr('min','分钟')}</span></div><h2 tabindex="-1" id="stage-title">${tr(t[0],t[1])}</h2><p>${tr(t[2],t[3])}</p></header>${stageBody()}${teacher?teacherPanel():''}<footer class="stage-footer">${i?button('Previous stage','上一阶段','previous','quiet'):button('Lesson home','课程首页','home','quiet')}<span class="small muted" id="save-status">${tr('Saved in this browser','已保存在此浏览器')}</span>${state.stage==='design'?'':state.stage==='setup'?button('Continue Main Task 1','继续主任务 1','continue-main1','primary'):i<9?button('Next stage','下一阶段','next','primary'):button('Save my PDF','保存我的 PDF','pdf','primary')}</footer></main></div>`;}
function stageBody(){return ({read:readPage,starter:starterPage,learning:learningPage,setup:setupPage,investigate:investigatePage,reset:resetPage,design:designPage,challenge:challengePage,pitstop:pitstopPage,finish:finishPage})[state.stage]();}
function readPage(){return `<div class="four">${[['Inform','提供信息','Share facts, ideas or a useful guide.','分享知识、想法或实用指南。'],['Showcase','展示内容','Present products, artwork or a collection.','展示产品、艺术作品或收藏。'],['Entertain','提供乐趣','Create a story, quiz or small game.','创作故事、测验或小游戏。'],['Express','表达自我','Share an interest, opinion or creative idea.','分享兴趣、观点或创意。']].map(a=>`<article class="purpose"><h3>${tr(a[0],a[1])}</h3><p>${tr(a[2],a[3])}</p></article>`).join('')}</div><div class="note">${tr('These are possibilities, not choices you must copy. Any school-appropriate topic is welcome. Focus on one feature first.','这些只是启发，不是必须照搬的选项。任何适合学校的主题都可以。先专注一个功能。')}</div><section class="card"><h3>${tr('Three ideas you will use today','今天会用到的三个概念')}</h3><div class="definitions">${D.glossary.slice(0,3).map(x=>`<article class="definition"><h3>${tr(x[0],x[1])}</h3><p>${tr(x[2],x[3])}</p></article>`).join('')}</div></section><section class="card"><h3>${tr('Follow the event and response','跟着事件和回应理解')}</h3><div class="flow"><div class="cell"><small>${tr('User event','用户事件')}</small><p>${tr('A reader selects “Explore the cave”.','读者选择“探索洞穴”。')}</p></div><span class="arrow" aria-hidden="true">→</span><div class="cell"><small>${tr('App response','应用的回应')}</small><p>${tr('The cave scene and its next choices appear.','显示洞穴场景和下一步的选择。')}</p></div></div><p class="small muted" style="margin-top:20px">${tr('The selection triggers programmed instructions. A good design explains both the action and what happens next.','选择操作触发程序指令。好的设计会说明用户做什么，以及接下来发生什么。')}</p>${guide('01-app-possibilities.png')}</section><div class="card tint"><h3>${tr('Your outcome today','今天的成果')}</h3><p>${tr('A brief for your own app, a labelled first-screen sketch, two action–response descriptions and one marked improvement.','你自己的应用简介、标注好的初始界面草图、两组“操作—回应”说明，以及一项标出的改进。')}</p><p class="small" style="margin:0">${tr('You can write short phrases or use Mandarin notes. The important part is making your idea clear.','可以写短语或使用中文笔记。关键是清楚表达你的想法。')}</p></div>`;}
function starterPage(){const score=Object.keys(state.answers).filter(i=>state.answers[i]===D.quiz[i].answer).length;return `${D.quiz.map((q,i)=>`<section class="card"><fieldset class="quiz-card"><legend><span class="q-number">${i+1}</span>${pair(q.q)}</legend>${q.options.map((o,j)=>`<label class="option ${state.checked&&q.answer===j?'correct':''}"><input type="radio" name="q${i}" data-bind="answers.${i}" value="${j}" ${state.answers[i]===j?'checked':''}> <span>${pair(o)}</span></label>`).join('')}${state.checked?`<div class="feedback ${state.answers[i]!==q.answer?'retry':''}"><strong>${state.answers[i]===undefined?tr('Not attempted yet','还未尝试'):state.answers[i]===q.answer?tr('Correct','正确'):tr('Review this idea','回顾这个概念')}</strong>${pair(q.feedback)}</div>`:''}</fieldset></section>`).join('')}<div class="row">${button('Check my answers','检查答案','check-starter','primary')}${state.checked?`<span>${tr(`${score} of 4 correct; ${4-Object.keys(state.answers).length} not attempted.`,`${score}/4 正确；${4-Object.keys(state.answers).length} 题尚未尝试。`)}</span>`:''}</div>`;}
function focusSummary(){const f=C.learningFocus(state),names=f.winners.map(a=>D.areas[a][state.lang==='bi'?1:0]);const counts=Object.fromEntries(['K','S','U'].map(a=>[a,f.counts[a]||0]));let msg=f.max?(f.winners.length===1?tr(`${D.areas[f.winners[0]][0]} is your main focus: you selected ${f.max} checks to practise in this area.`,`${names[0]}是你的主要重点：你在这个领域选择了 ${f.max} 项需要练习的内容。`):tr('Your focus is shared across '+f.winners.map(a=>D.areas[a][0]).join(' and ')+'. Work on one small step at a time.','你的重点分布在'+names.join('和')+'。一次专注一个小步骤。')):tr('Choose the checks you want to practise today. “Not tried yet” stays separate from “needs practice”.','选择今天想练习的项目。“尚未尝试”与“需要练习”分开记录。');const next={K:['Reread a definition and match an event to its response.','重读定义，再把事件与回应配对。'],S:['Use the two-column table, then label one control at a time.','先用两列表格，再逐个标注控件。'],U:['Ask what the user expects, and explain how your label or content helps.','想一想用户期待什么，再解释标签或内容如何帮助用户。']};return `<div class="focus-summary"><strong>${tr('Your focus today','今天的学习重点')}</strong><div class="count-strip">${['K','S','U'].map(a=>`<div><b>${counts[a]}</b>${pair(D.areas[a])}</div>`).join('')}</div><p>${msg}</p>${f.max?`<p class="small" style="margin:0">${pair(next[f.winners[0]])}</p>`:''}</div>`;}
function learningPage(){return `<div class="note">${tr('“Already secure” is useful prior learning. Design skills you have not used today can stay “Not tried yet”. You can focus on more than one area.','“已经掌握”是有价值的已有知识。今天尚未使用的设计技能可以标为“尚未尝试”。你可以关注不止一个领域。')}</div><div class="three">${['K','S','U'].map(a=>`<section class="card compact"><span class="chip">${a}</span><h3 style="margin-top:14px">${pair(D.areas[a])}</h3>${C.checks.filter(c=>c.area===a).map(c=>`<div class="learning-row"><p>${tr(c.en,c.zh)}</p><small class="muted">${esc(c.evidence)}</small><div class="segmented">${[['secure','Already secure','已经掌握'],['focus','Practise today','今天练习'],['untried','Not tried yet','尚未尝试']].map(([v,en,zh])=>`<label><input type="radio" name="learn-${c.id}" data-bind="learning.${c.id}" value="${v}" ${(state.learning[c.id]||'untried')===v?'checked':''}><span>${tr(en,zh)}</span></label>`).join('')}</div></div>`).join('')}</section>`).join('')}</div><div id="focus-summary">${focusSummary()}</div>`;}
function setupPage(){let n=state.setup.step,a=D.access[n];const allowed=state.setup.route==='existing'?[0,3,4]:[0,1,2,3,4];return `<section class="card tint"><h3>${tr('School email, separate MIT account','学校邮箱，单独的 MIT 账户')}</h3><p>${tr('Your school email uses Microsoft/Teams. Follow MIT’s email-account route below. This lesson never asks you to enter your email code or password here.','学校邮箱使用 Microsoft/Teams。请按下面的 MIT 邮箱注册步骤进行。本课页面不会要求你在这里输入验证码或密码。')}</p><div class="status-choice">${[['new','I am new to MIT','我是 MIT 新用户'],['existing','I already have an MIT account','我已有 MIT 账户']].map(([v,en,zh])=>`<label class="option"><input type="radio" name="route" data-bind="setup.route" value="${v}" ${state.setup.route===v?'checked':''}><span>${tr(en,zh)}</span></label>`).join('')}</div></section><div class="task-tabs" aria-label="MIT setup cards">${allowed.map(i=>`<button data-setup-step="${i}" class="${i===n?'active':''}">A${i+1} · ${tr(i===0?'Login':i===1?'Request code':i===2?'Enter code':i===3?'Welcome':'Access check',i===0?'登录':i===1?'申请验证码':i===2?'输入验证码':i===3?'欢迎通知':'确认访问')}</button>`).join('')}</div><section class="card"><div class="eyebrow">A${n+1} / A5</div><h3>${pair(a.title)}</h3><ol class="steps">${a.steps.map(s=>`<li>${pair(s)}</li>`).join('')}</ol><div class="row" style="margin-top:24px"><a class="btn primary" href="https://login.appinventor.mit.edu/login/" target="_blank" rel="noopener">${tr('Open MIT login','打开 MIT 登录')} ↗</a>${n===1?`<a class="btn" href="https://outlook.office.com/mail/" target="_blank" rel="noopener">${tr('Open school Outlook','打开学校 Outlook')} ↗</a>`:''}</div>${shot(a.screen,a.title[0]+' — genuine MIT screenshot',a.guide)}<div class="note">${pair(a.note)}</div><div class="row spread">${allowed.indexOf(n)>0?button('Previous card','上一张','setup-prev','quiet'):'<span></span>'}${n<4?button('Next setup card','下一张设置卡片','setup-next','primary'):button('Continue Main Task 1','继续主任务 1','continue-main1','primary')}</div></section><section class="card"><h3>${tr('Record your access status','记录账户访问状态')}</h3><p class="small muted">${tr('Waiting for an email is an access problem, not a computing score. You can continue the lesson.','等待邮件是账户访问问题，不代表计算机知识水平。你可以继续学习。')}</p><div class="status-choice">${[['ready','Access is working','已成功进入'],['waiting','Waiting for email','等待邮件'],['help','Need access help','需要账户帮助']].map(([v,en,zh])=>`<label class="option"><input name="setup-status" type="radio" data-bind="setup.status" value="${v}" ${state.setup.status===v?'checked':''}><span>${tr(en,zh)}</span></label>`).join('')}</div></section>`;}
function pairsEditor(prefix){return `<div class="table-head"><span>${tr('User action / event','用户操作 / 事件')}</span><span>${tr('App response','应用的回应')}</span></div>${[0,1].map(i=>`<div class="pair-row"><div>${field(`${i+1}. When the user…`,`${i+1}. 当用户……`,`${prefix}.pairs.${i}.action`,'textarea',state.guided?tr('Name the control and the action.','写出控件名称和操作。'):'',state.lang==='bi'?'例如：用户选择……':'e.g. selects…')}</div><div>${field('The app…','应用就……',`${prefix}.pairs.${i}.response`,'textarea',tr('Name what appears, changes or plays.','具体写出显示、改变或播放什么。'),state.lang==='bi'?'显示 / 改变 / 播放……':'shows / changes / plays…')}</div></div>`).join('')}`;}
function exampleTable(){return `<div class="table-head"><span>${tr('User action','用户操作')}</span><span>${tr('App response','应用的回应')}</span></div>${D.examples.map(e=>`<div class="example-row"><p><small>${pair(e.title)}</small>${pair(e.action)}</p><p>${pair(e.response)}</p></div>`).join('')}`;}
function investigatePage(){return `<section class="card"><h3>${tr('Do these three things','完成三个步骤')}</h3><ol class="steps"><li>${tr('Choose an app you already know and can view. Spend no more than one minute choosing.','选择一个你已经熟悉、可以查看的应用。选择时间不超过一分钟。')}</li><li>${tr('Find two actions. Notice what appears, changes or plays after each one.','找出两个操作，观察每个操作后显示、改变或播放了什么。')}</li><li>${tr('Complete the two rows below. Then name one helpful label and say why it helps.','完成下面两行，再指出一个有帮助的标签，简短说明原因。')}</li></ol><div class="note">${tr('Use an app you can already access. If you cannot open one, use two provided examples below.','使用已经可以访问的应用。如果无法打开应用，就使用下面提供的两个例子。')}</div>${guide('02-investigate-an-app.png')}</section><section class="card"><div class="status-choice">${[['own','I am studying an app I know','我研究熟悉的应用'],['provided','I am using provided examples','我使用提供的例子']].map(([v,en,zh])=>`<label class="option"><input type="radio" name="source" data-bind="investigate.source" value="${v}" ${state.investigate.source===v?'checked':''}><span>${tr(en,zh)}</span></label>`).join('')}</div>${state.investigate.source==='provided'?`<div style="margin-top:24px">${exampleTable()}<p class="small muted">${tr('Use any two examples to identify the action and response. Your own app can have another topic.','选择任意两个例子识别操作与回应。你自己的应用可以使用其他主题。')}</p></div>`:''}${field('App name, or write “provided examples”','应用名称，或填写“提供的例子”','investigate.app','text')}${pairsEditor('investigate')}</section><section class="card"><h3>${tr('Notice one useful label','观察一个有用的标签')}</h3>${field('Which control label is clear?','哪个控件标签很清楚？','investigate.label')}${field('Why does it help the user?','它为什么能帮助用户？','investigate.reason','textarea',tr('A short phrase is enough. Say what it tells the user.','简短短语即可。说明它让用户知道什么。'),state.guided?'It tells the user… / 它告诉用户……':'')}</section>`;}
const resetQs=[['Tapping a picture is the event; its description appearing is the response.','点击图片是事件；图片介绍出现是回应。',true,'The action triggers the change.','操作触发了变化。'],['An attractive title alone tells the user what every control will do.','只要标题好看，用户就知道每个控件会做什么。',false,'Controls need useful labels and predictable responses too.','控件也需要有用的标签和可预期的回应。'],['Two apps with different topics can both respond to user events.','主题不同的两个应用都可以回应用户事件。',true,'The topic is your choice; the event–response relationship still matters.','主题由你选择；“事件—回应”的关系仍然重要。']];
function resetPage(){const n=state.reset.index,q=resetQs[n],a=state.reset.answers[n];return `<section class="card dark"><div class="eyebrow">${n+1} / 3</div><h3 style="font-size:1.7rem;line-height:1.5">${tr(q[0],q[1])}</h3><div class="row">${button('True','正确','reset-answer','lime',`data-value="true"`)}${button('False','错误','reset-answer','',`data-value="false"`)}</div>${typeof a==='boolean'?`<div class="feedback" style="color:var(--ink)"><strong>${a===q[2]?tr('You spotted it','你发现了'):tr('Try the explanation','看看解释')}</strong>${tr(q[3],q[4])}</div>`:''}</section><div class="row spread">${n?button('Previous question','上一题','reset-prev','quiet'):'<span></span>'}${n<2?button('Next question','下一题','reset-next','primary'):button('Start my own design','开始自己的设计','start-design','primary')}</div>`;}
function designPage(){const d=state.design,step=d.step,titles=[['Choose','选择'],['Sketch','画草图'],['Interactions','描述互动'],['Improve','改进']];return `<div class="project-ribbon"><span>${tr('One app, all four steps','四个步骤，同一个应用')}:</span><strong id="project-name">${esc(d.title)||tr('Your app idea','你的应用想法')}</strong></div><div class="substeps" aria-label="Your app design steps">${titles.map((t,i)=>`<button data-design-step="${i}" class="${i===step?'active':''}">${i+1}. ${pair(t)}</button>`).join('')}</div>${[designChoose,designSketch,designInteractions,designImprove][step]()}<div class="row spread" style="margin-top:25px">${step?button('Previous design step','上一个设计步骤','design-prev','quiet'):'<span></span>'}${step<3?button('Next design step','下一个设计步骤','design-next','primary'):button('Design complete — continue','设计完成，继续','design-done','primary')}</div>`;}
function designChoose(){return `<section class="card"><div class="eyebrow">1 / 4 · Choose</div><h3>${tr('Make your idea clear','说清楚你的想法')}</h3><p>${tr('Choose any appropriate topic. Your app can inform, showcase, entertain, express or do something else useful. Start with one feature.','可以选择任何适合学校的主题。应用可以提供信息、展示、娱乐、表达，或完成其他有用的事情。先选一个功能。')}</p>${field('My app’s name','应用名称','design.title','text','','Choose your own name / 自己命名')}${field('My app is about…','我的应用主题是……','design.topic','textarea','',state.guided?'a topic / product / interest / story / 主题、产品、兴趣或故事':'')}${field('It is for…','目标用户是……','design.audience','text',tr('Name a group of people, rather than just “everyone”.','写出一类用户，而不只是“所有人”。'))}${field('The first feature lets the user…','第一个功能让用户可以……','design.feature','textarea',tr('Describe one thing a person should be able to do. Short phrases or Mandarin notes are fine.','说明用户可以完成的一件事。可以用短语或中文笔记。'))}${guide('03-choose-your-app.png')}</section>`;}
function designSketch(){const d=state.design;return `<section class="card"><div class="eyebrow">2 / 4 · Sketch</div><h3>${tr('Design the first screen for the same app','为同一个应用设计初始界面')}</h3><ol class="steps"><li>${tr('Include your app’s title and the content its audience needs.','加入应用标题和目标用户需要的内容。')}</li><li>${tr('Show controls for two useful actions. They can be buttons, menu choices, pictures or inputs.','画出两个有用操作所需的控件，可以是按钮、菜单选项、图片或输入框。')}</li><li>${tr('Give controls clear labels. Use your own layout.','给控件清楚的标签，布局由你决定。')}</li></ol>${guide('04-sketch-your-screen.png')}<div class="status-choice" style="margin-top:20px">${[['digital','Use the digital sketch board','使用数字草图板'],['paper','Draw on paper / add a photo','画在纸上 / 添加照片']].map(([v,en,zh])=>`<label class="option"><input type="radio" name="sketch-method" data-bind="design.method" value="${v}" ${d.method===v?'checked':''}><span>${tr(en,zh)}</span></label>`).join('')}</div></section>${d.method==='digital'?`<section class="card"><h3>${tr('Your screen sketch','你的界面草图')}</h3><p class="small">${tr('Add an element, change its label in the label box, then drag it into place. This is your design sketch for the later MIT project.','添加一个元素，在标签框中修改文字，再拖动到合适位置。这是以后 MIT 项目的设计草图。')}</p><div class="builder-toolbar">${[['text','Text','文字'],['button','Button','按钮'],['image','Picture','图片'],['input','Input','输入框'],['menu','Menu','菜单']].map(([v,en,zh])=>button('+ '+en,zh,'add-node','small',`data-value="${v}"`)).join('')}${button('Undo','撤销','undo','small',undo.length?'':'disabled')}</div><div class="sketch-editor"><div><div class="board" id="sketch-board" aria-label="Your editable screen sketch">${d.nodes.length?d.nodes.map(nodeHTML).join(''):`<div class="board-empty"><strong>${tr('Start with a title','先添加标题')}</strong><p>${tr('Select + Text, then write your app’s name. Add the content and controls your idea needs.','选择 + Text，再写上应用名称。然后添加你的想法需要的内容和控件。')}</p></div>`}</div><p class="sketch-hint">${tr('Touch: drag an element. Keyboard: select it, then use arrow keys to move it. Use the label box to edit its text.','触摸：拖动元素。键盘：选中元素后用方向键移动。在标签框中编辑文字。')}</p></div><div id="inspector">${inspector()}</div></div></section>`:`<section class="card"><h3>${tr('Keep your paper sketch','保留纸上草图')}</h3><p>${tr('Draw a labelled first screen. Add a photo here if you want it included in your PDF. Otherwise, keep the paper with your report.','画出标注清楚的初始界面。如果希望 PDF 包含草图，请在这里添加照片；否则把纸上草图和报告保存在一起。')}</p><label class="check"><input type="checkbox" data-bind="design.paper" ${d.paper?'checked':''}><span>${tr('I have drawn my first screen on paper.','我已经在纸上画好初始界面。')}</span></label><label class="field">${tr('Add a photo of your sketch','添加草图照片')}<input id="sketch-photo" type="file" accept="image/png,image/jpeg,image/webp"></label>${d.photo?`<img class="photo-preview" src="${d.photo}" alt="Your uploaded sketch">${button('Remove photo','移除照片','remove-photo','small quiet')}`:''}</section>`}`;}
function nodeHTML(n){return `<button type="button" class="sketch-item type-${n.type} ${selected===n.id?'selected':''}" style="left:${n.x}%;top:${n.y}%" data-node="${esc(n.id)}" aria-label="${esc(n.type+': '+n.label+'. Select to edit or move with arrow keys.')}">${esc(n.label)}</button>`;}
function inspector(){const n=state.design.nodes.find(x=>x.id===selected);return n?`<div class="inspector"><label class="field">${tr('Label / content of the selected element','选中元素的标签 / 内容')}<input id="node-label" data-node-label="${esc(n.id)}" maxlength="80" value="${esc(n.label)}"></label><div class="row"><span class="small muted">${tr('Use words that tell the user what this is or does.','用文字告诉用户这是什么或能做什么。')}</span>${button('Delete this element','删除这个元素','delete-node','small')}</div></div>`:`<div class="inspector small muted">${tr('Select an element to edit its label. You can move it by dragging or using arrow keys.','选中元素以编辑标签。可以拖动或用方向键移动。')}</div>`;}
function designInteractions(){return `<section class="card"><div class="eyebrow">3 / 4 · Interactions</div><h3>${tr('Describe two actions from your own sketch','描述你草图中的两个操作')}</h3><p>${tr('Use the same control labels as your sketch. Name the exact content, screen, change or sound that follows each action.','使用草图中相同的控件标签。准确说明每个操作之后出现的内容、界面、变化或声音。')}</p><details><summary>${tr('See examples from different app types','查看不同应用类型的例子')}</summary>${exampleTable()}</details><div class="note">${tr('“The app works” is too vague. Say what appears, changes or plays. A new screen can be described with a short note or small sketch.','“应用正常工作”不够具体。说明显示、改变或播放什么。新界面可以用简短说明或小图表示。')}</div>${pairsEditor('design')}${guide('05-specify-interactions.png')}</section>`;}
function designImprove(){const d=state.design;return `<section class="card"><div class="eyebrow">4 / 4 · Improve</div><h3>${tr('Walk through the same design','逐步检查同一个设计')}</h3><ol class="steps"><li>${tr('Point to the first control in your sketch. Read its action and response. Check that they match.','指向草图中第一个控件，读出它的操作与回应，检查两者是否匹配。')}</li><li>${tr('Do the same for the second action. Can your intended user tell what will happen?','同样检查第二个操作。目标用户能知道将发生什么吗？')}</li><li>${tr('Improve one unclear label, missing detail, response or awkward layout. Mark or record the change.','改进一个不清楚的标签、缺少的细节、不明确的回应或不方便的布局，并标出或记录修改。')}</li></ol>${[0,1].map(i=>`<label class="check"><input type="checkbox" data-bind="design.review.${i}" ${d.review[i]?'checked':''}><span>${tr(`I walked through action ${i+1} and checked its response.`,`我逐步检查了操作 ${i+1} 及其回应。`)}</span></label>`).join('')}${field('The part I improved','我改进的部分','design.changeArea','text','','label / content / response / layout')}${field('My change','我的修改','design.change','textarea',tr('A short note is enough. For example: “Go” → “Read player profile”. Your change should fit your own app.','简短说明即可。例如：“Go” → “Read player profile”。修改应符合自己的应用。'))}${guide('06-walkthrough-and-save.png')}</section>`;}
const challenges=[['screen','Design a second screen','设计第二个界面','Show how the user reaches it and returns to the first screen.','说明用户如何进入第二个界面，再返回第一个界面。'],['choice','Add a meaningful choice','增加有意义的选择','Describe different responses to two choices in the same feature.','为同一个功能中的两个选择描述不同回应。'],['access','Make it easier to access','让应用更易使用','Improve a label, readability, or a text alternative to a sound. Explain the benefit briefly.','改进标签、文字可读性，或为声音加入文字替代。简短说明好处。']];
function challengePage(){return `<section class="card"><h3>${tr('Build on the same app idea','继续完善同一个应用想法')}</h3><div class="note">${tr('If you have time after the main design, choose one challenge. Add to your existing sketch or notes.','主要设计完成后，如果还有时间，选择一个挑战。在已有草图或笔记上继续完善。')}</div>${challenges.map(([v,en,zh,desc,dzh])=>`<label class="option"><input type="radio" name="challenge" data-bind="challenge.choice" value="${v}" ${state.challenge.choice===v?'checked':''}><span><strong>${tr(en,zh)}</strong><span class="small" style="display:block;margin-top:8px">${tr(desc,dzh)}</span></span></label>`).join('')}${field('My added idea or change','我增加的想法或修改','challenge.note','textarea',tr('Short notes, arrows or an updated sketch are enough.','简短笔记、箭头或更新的草图即可。'))}</section><section class="card tint"><h3>${tr('Ready to explore the editor?','准备好探索编辑器了吗？')}</h3><p>${tr('After your design is complete, these references show how to create one blank project with your own app name and find it again. You do not need to program it today.','完成设计后，这些参考指南会教你用自己的应用名称创建一个空白项目，并再次找到它。今天不需要编程。')}</p>${referenceButtons()}</section>`;}
function phaseSummary(){const v=Object.values(state.pitstop),f=C.dominance(v);if(!f.total)return `<p>${tr('Choose a phase for each area. Your quiz score will not choose it for you.','为每个领域选择状态。测验分数不会自动决定你的学习状态。')}</p>`;const names=f.winners.map(k=>D.phases[k][0]),zh=f.winners.map(k=>D.phases[k][1]);return `<strong>${f.winners.length===1?tr(`${names[0]} is your most selected phase (${f.max} of ${f.total} areas).`,`${zh[0]}是你选择最多的状态（${f.total} 个领域中有 ${f.max} 个）。`):tr('Your confidence is mixed: '+names.join(' and ')+'.','你的学习状态不同：'+zh.join('、')+'。')}</strong><p class="small" style="margin:12px 0 0">${tr('Keep the individual choices too. You may feel secure with the vocabulary and still find designing responses difficult.','每个领域的选择都重要。你可能熟悉词汇，但设计回应仍有困难。')}</p>`;}
function pitstopPage(){return `${['K','S','U'].map(a=>`<section class="card"><span class="goal-area">${a} · ${pair(D.areas[a])}</span><h3 style="margin-top:12px">${pair(D.goals[a])}</h3><div class="phases-grid">${Object.entries(D.phases).map(([v,p])=>`<label class="phase"><input type="radio" name="phase-${a}" data-bind="pitstop.${a}" value="${v}" ${state.pitstop[a]===v?'checked':''}><span><strong>${tr(p[0],p[1])}</strong><small>${tr(p[2],p[3])}</small></span></label>`).join('')}</div></section>`).join('')}<div class="focus-summary" id="phase-summary">${phaseSummary()}</div>`;}
function completion(){const done=C.completeness(state),labels={brief:['My app’s purpose and audience','应用用途和目标用户'],sketch:['My labelled first-screen sketch','标注好的初始界面草图'],interactions:['Two action–response descriptions','两组“操作—回应”说明'],improvement:['One recorded improvement','记录的一项改进']};return `<div class="completion-list">${Object.entries(done).map(([k,v])=>`<div class="${v?'met':''}"><b>${v?'✓':'○'}</b>${pair(labels[k])}${!v?`<small class="muted" style="display:block">${tr('Check this before submitting.','提交前检查这一项。')}</small>`:''}</div>`).join('')}</div>`;}
function finishPage(){return `<section class="card"><h3>${tr('Explain what you designed','解释你的设计')}</h3>${field('One event and its response in my app','我的应用中的一个事件和它的回应','plenary.event','textarea',tr('You may use one of your interaction rows. Name both the user action and what the app does.','可以使用你写好的一组互动。写出用户操作和应用如何回应。'))}${state.design.pairs[0].action?button('Use my first interaction','使用第一个互动','use-interaction','small'):''}${field('How does one control or piece of content help my audience?','一个控件或一项内容如何帮助目标用户？','plenary.reason','textarea',tr('A short reason is enough. Think about what your intended user needs.','简短理由即可。想想目标用户需要什么。'))}</section><section class="card"><h3>${tr('Check, save, submit','检查、保存、提交')}</h3>${completion()}<ol class="steps"><li>${tr('Save your PDF. In the print window, choose Save as PDF; on iPad, use the print preview or Share to save the PDF to Files.','保存 PDF。在打印窗口选择“另存为 PDF”；iPad 可通过打印预览或“共享”把 PDF 保存到“文件”。')}</li><li>${tr('Open the PDF and check that your design and responses are included. If your sketch is on paper without a photo, keep it with the report.','打开 PDF，检查设计和答案是否完整。如果纸上草图没有添加照片，请把它和报告保存在一起。')}</li><li>${tr('Upload the PDF in Teams where your teacher directs you.','按老师要求，在 Teams 中上传 PDF。')}</li></ol><div class="row" style="margin-top:24px">${button('Save my PDF','保存我的 PDF','pdf','primary')}${button('Preview my report','预览报告','report','')}</div><details style="margin-top:24px"><summary>${tr('Other copies and backup','其他副本与备份')}</summary><p class="small">${tr('A backup keeps editable responses for this lesson app. The readable report is an HTML copy you can open in a browser. Your main submission is the PDF.','备份用于恢复本课应用中可编辑的答案。可读报告是能在浏览器中打开的 HTML 副本。主要提交文件是 PDF。')}</p><div class="row">${button('Download full backup','下载完整备份','backup','small')}${button('Download readable report','下载可读报告','html-report','small')}<label class="btn small">${tr('Restore a backup','恢复备份')}<input type="file" id="restore-file" accept="application/json,.json" hidden></label></div></details></section>`;}
function referenceButtons(){return `<div class="resource-list">${D.references.map(r=>`<button data-reference="${r[0]}">${tr(r[1],r[2])} ↗</button>`).join('')}</div>`;}
function teacherPanel(){return `<details class="teacher"><summary>Teacher guidance · 60-minute lesson</summary><p>Core outcome: one app brief, a labelled first screen, two precise interactions and one improvement. Topic, audience and layout remain the student’s choice. Short phrases and Mandarin notes are acceptable.</p><table><tbody>${C.stages.map(s=>`<tr><td>${s[1]}</td><td>${s[3]} min</td></tr>`).join('')}</tbody></table><p>MIT: school-email registration, separate MIT password. Core setup ends at the project list. Allow waiting students to continue after checking Junk once. Password creation is described; its screen was not captured. Neo workspace, blank-project saving and reopening were checked. The return check used the existing signed-in session, not a new password login.</p><p>Do now answers: 1 A, 2 B, 3 C, 4 B. Main Task 1: accept precise equivalent descriptions. Provided examples are valid support; record their source. Main Task 2: judge the four requirements, not artistic quality or English fluency.</p><p>Example interaction: selecting a music artist opens their profile; choosing a story path opens that scene; selecting an artwork displays its caption. These are examples, not assigned projects.</p><p>Types of Learning counts chosen practice areas. Pit Stop counts self-reported confidence. Neither is automatically inferred from quiz marks. The “one step at a time” setting adds prompts and is available to everyone.</p><a href="assets/MIT_School_Email_Access_Guide.pdf" target="_blank" rel="noopener">MIT guide PDF</a> · <a href="assets/Year9_Your_App_Activity_Guides.pdf" target="_blank" rel="noopener">Activity guide PDF</a></details>`;}
function render(heading=false){const active=document.activeElement,path=active?.dataset?.bind,start=active?.selectionStart,end=active?.selectionEnd;$('#app').innerHTML=state.joined?shell():landing();if(path){const el=[...document.querySelectorAll('[data-bind]')].find(e=>e.dataset.bind===path&&(e.type!=='radio'||e.value===active.value));if(el){el.focus({preventScroll:true});if(typeof start==='number'&&['text','textarea'].includes(el.type))el.setSelectionRange(start,end);}}if(heading)$('#stage-title')?.focus({preventScroll:true});}
function go(id){if(!C.stages.some(s=>s[0]===id))return;state.stage=id;save();if(location.hash!==`#${id}`)location.hash=id;render(true);scrollTo({top:0,behavior:'instant'});}
function next(){if(!state.done.includes(state.stage))state.done.push(state.stage);const i=C.stages.findIndex(s=>s[0]===state.stage);go(C.stages[Math.min(9,i+1)][0]);}
function showDialog(title,html){$('#resource-content').innerHTML=`<header class="dialog-head"><strong>${title}</strong>${button('Close','关闭','close-dialog','small')}</header><div class="dialog-body">${html}</div>`;const d=$('#resource-dialog');if(!d.open)d.showModal();}
function openImage(src,title){showDialog(esc(title),`<img src="${esc(src)}" alt="${esc(title)}">`);}
function resources(){showDialog(tr('Your visual guides','图示指南'),`<p>${tr('Use a guide for the stage you are on. Editor references are for after your design is complete.','使用当前阶段对应的指南。完成设计后再查看编辑器参考。')}</p><h3>${tr('Activity guides','活动指南')}</h3><div class="resource-list">${[['01-app-possibilities.png','Read first','先读一读'],['02-investigate-an-app.png','Investigate an app','研究应用'],['03-choose-your-app.png','Choose your app','选择自己的应用'],['04-sketch-your-screen.png','Sketch your screen','画界面草图'],['05-specify-interactions.png','Describe interactions','描述互动'],['06-walkthrough-and-save.png','Review your design','检查设计']].map(([f,en,zh])=>`<button data-guide="${f}">${tr(en,zh)} ↗</button>`).join('')}</div><h3 style="margin-top:25px">${tr('MIT editor references','MIT 编辑器参考')}</h3>${referenceButtons()}<div class="row" style="margin-top:25px"><a class="btn small" href="assets/MIT_School_Email_Access_Guide.pdf" target="_blank" rel="noopener">${tr('MIT guide PDF','MIT 指南 PDF')}</a><a class="btn small" href="assets/Year9_Your_App_Activity_Guides.pdf" target="_blank" rel="noopener">${tr('Activity guide PDF','活动指南 PDF')}</a></div>`);}
function rememberNodes(){undo.push(JSON.stringify(state.design.nodes));if(undo.length>20)undo.shift();const b=document.querySelector('[data-act="undo"]');if(b)b.disabled=false;}
function clampNode(n){n.x=Math.max(0,Math.min(n.type==='text'?56:n.type==='image'?72:70,n.x));n.y=Math.max(0,Math.min(n.type==='image'?76:85,n.y));}
function addNode(type){if(state.design.nodes.length>=30)return toast('Use the elements you have, or delete one first.','请使用已有元素，或先删除一个。');rememberNodes();const count=state.design.nodes.length,n={id:'n'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),type,label:{text:state.design.title||'Your text',button:'Label this button',image:'Describe this picture',input:'What should the user type?',menu:'Label this menu'}[type],x:8+count%3*9,y:8+count%5*14};selected=n.id;state.design.nodes.push(n);save();render();}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function fileName(ext){return (state.student.name||'Year9').replace(/[^\p{L}\p{N}_-]/gu,'_')+'-App-Design.'+ext;}
async function sketchPNG(){const d=state.design;if(d.method==='paper')return d.photo;await document.fonts.ready;const cv=document.createElement('canvas');cv.width=1100;cv.height=710;const x=cv.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,1100,710);x.strokeStyle='#9fb5a5';x.strokeRect(2,2,1096,706);for(const n of d.nodes){const left=n.x*11,top=n.y*7.1,w=(n.type==='text'?44:n.type==='image'?28:30)*11,h=(n.type==='image'?24:15)*7.1;x.fillStyle=n.type==='button'?'#eaf2df':n.type==='image'?'#edf1e9':'#fff';x.strokeStyle='#6b8974';x.fillRect(left,top,w,h);x.strokeRect(left,top,w,h);x.fillStyle='#203c30';x.font='23px Raleway, sans-serif';let yy=top+31,line='';const tokens=/\s/.test(n.label)?n.label.split(/\s+/):Array.from(n.label);for(const t of tokens){const next=line+(line&&/\s/.test(n.label)?' ':'')+t;if(x.measureText(next).width>w-26&&line){x.fillText(line,left+13,yy);yy+=29;line=t;}else line=next;}if(line)x.fillText(line,left+13,yy);}return cv.toDataURL('image/png');}
async function openReport(print=false){const win=window.open('about:blank','_blank');if(!win)return toast('Allow this report to open in a new tab, then try again.','请允许报告在新标签页打开，然后再试。');save();const image=await sketchPNG();try{sessionStorage.setItem(C.KEY+'-sketch',image||'');win.sessionStorage.setItem(C.KEY+'-sketch',image||'');}catch(e){}const url=new URL(location.href);url.hash='';url.search='?report=1'+(print?'&print=1':'');win.location.replace(url.href);}
async function handleAction(act,el){switch(act){case'new-response':if(confirm('Start a new response? Save your PDF or backup first. / 开始新的答卷？请先保存 PDF 或备份。')){const lang=state.lang;state=C.initial();state.lang=lang;undo=[];selected=null;save();history.replaceState(null,'',location.pathname+location.search);render();scrollTo(0,0);}return;case'next':return next();case'previous':return go(C.stages[Math.max(0,C.stages.findIndex(s=>s[0]===state.stage)-1)][0]);case'home':state.joined=false;save();render();return;case'identity':showDialog(tr('Your details and support','个人信息与支持'),`${field('Name','姓名','student.name')}${field('Class / form','班级','student.form')}<label class="check"><input type="checkbox" data-bind="guided" ${state.guided?'checked':''}><span>${tr('One step at a time — extra prompts','一步一步完成——更多提示')}</span></label>${button('Done','完成','close-dialog','primary')}`);return;case'mobile-goals':$('#layout').classList.toggle('goals-open');return;case'glossary':showDialog(tr('Words that help','有用的词汇'),`<div class="glossary">${D.glossary.map(g=>`<article><h3>${esc(g[0])}<span class="zh" lang="zh-Hans">${esc(g[1])}</span></h3><p>${tr(g[2],g[3])}</p></article>`).join('')}</div>`);return;case'resources':return resources();case'close-dialog':$('#resource-dialog').close();render();return;case'check-starter':state.checked=true;save();render();return;case'setup-next':case'setup-prev':{const steps=state.setup.route==='existing'?[0,3,4]:[0,1,2,3,4],i=steps.indexOf(state.setup.step);state.setup.step=steps[Math.max(0,Math.min(steps.length-1,i+(act==='setup-next'?1:-1)))];save();render();$('#stage-title').scrollIntoView();return;}case'continue-main1':if(!state.done.includes('setup'))state.done.push('setup');return go('investigate');case'reset-answer':state.reset.answers[state.reset.index]=el.dataset.value==='true';save();render();return;case'reset-prev':case'reset-next':state.reset.index=Math.max(0,Math.min(2,state.reset.index+(act==='reset-next'?1:-1)));save();render();return;case'start-design':return go('design');case'design-next':case'design-prev':state.design.step=Math.max(0,Math.min(3,state.design.step+(act==='design-next'?1:-1)));save();render();$('#stage-title').scrollIntoView();return;case'design-done':return next();case'add-node':return addNode(el.dataset.value);case'delete-node':rememberNodes();state.design.nodes=state.design.nodes.filter(n=>n.id!==selected);selected=null;save();render();return;case'undo':if(undo.length)state.design.nodes=JSON.parse(undo.pop());selected=null;save();render();return;case'remove-photo':state.design.photo='';save();render();return;case'use-interaction':{const p=state.design.pairs[0];state.plenary.event=p.action+' → '+p.response;save();render();return;}case'pdf':return openReport(true);case'report':return openReport(false);case'backup':download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),fileName('json'));return;case'html-report':{const img=await sketchPNG();download(new Blob([window.LessonReport.html(state,img,true)],{type:'text/html;charset=utf-8'}),fileName('html'));return;}}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act],[data-stage],[data-guide],[data-image],[data-reference],[data-setup-step],[data-design-step]');if(!el)return;if(el.dataset.act)return void handleAction(el.dataset.act,el);if(el.dataset.stage)return go(el.dataset.stage);if(el.dataset.guide)return openImage('assets/guides/'+el.dataset.guide,'Activity guide');if(el.dataset.image)return openImage(el.dataset.image,el.dataset.title||'Screenshot');if(el.dataset.reference){const r=D.references.find(x=>x[0]===el.dataset.reference);return showDialog(tr(r[1],r[2]),`<div class="reference-note">${tr(r[3],r[4])}</div><img src="assets/guides/${r[0]}" alt="${esc(r[1])}">`);}if(el.dataset.setupStep!==undefined){state.setup.step=Number(el.dataset.setupStep);save();render();}if(el.dataset.designStep!==undefined){state.design.step=Number(el.dataset.designStep);save();render();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.nodeLabel){const n=state.design.nodes.find(x=>x.id===el.dataset.nodeLabel);if(n){n.label=el.value;const b=[...document.querySelectorAll('[data-node]')].find(x=>x.dataset.node===n.id);if(b){b.textContent=n.label;b.setAttribute('aria-label',n.type+': '+n.label+'. Select to edit or move with arrow keys.');}save();}return;}if(!el.dataset.bind||['radio','checkbox','file'].includes(el.type))return;set(el.dataset.bind,el.value);save();if(el.dataset.bind==='design.title'&&$('#project-name'))$('#project-name').textContent=el.value||'Your app idea';});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='language'){state.lang=el.value;save();render();return;}if(el.dataset.bind&&['radio','checkbox'].includes(el.type)){const p=el.dataset.bind;let v=el.type==='checkbox'?el.checked:el.value;if(p.startsWith('answers.'))v=Number(v);set(p,v);if(p==='setup.route'&&state.setup.route==='existing'&&[1,2].includes(state.setup.step))state.setup.step=0;save();render();return;}if(el.id==='sketch-photo'&&el.files[0]){const f=el.files[0];if(!/^image\/(png|jpeg|webp)$/.test(f.type))return toast('Choose a PNG, JPEG or WebP picture.','请选择 PNG、JPEG 或 WebP 图片。');const url=URL.createObjectURL(f),im=new Image();im.onload=()=>{const cv=document.createElement('canvas'),scale=Math.min(1,1400/Math.max(im.width,im.height));cv.width=Math.round(im.width*scale);cv.height=Math.round(im.height*scale);cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);state.design.photo=cv.toDataURL('image/jpeg',.82);URL.revokeObjectURL(url);save();render();};im.onerror=()=>{URL.revokeObjectURL(url);toast('This picture could not be opened.','无法打开这张图片。');};im.src=url;return;}if(el.id==='restore-file'&&el.files[0]){try{if(el.files[0].size>5000000)throw new Error('Backup is too large.');const restored=C.restore(JSON.parse(await el.files[0].text()));if(!confirm('Replace the current lesson responses with this backup? / 用备份替换当前答案？'))return;state=restored;save();render();toast('Backup restored.','已恢复备份。');}catch(err){toast('This backup could not be restored: '+err.message,'无法恢复此备份。');}}});
document.addEventListener('submit',e=>{if(e.target.id!=='entry-form')return;e.preventDefault();if(!state.student.name.trim())return toast('Enter your name to label your work.','请输入姓名，以标识你的作品。');state.guided=$('#entry-guided').checked||C.guidedName(state.student.name);if(C.guidedName(state.student.name))state.lang='bi';state.joined=true;save();go(state.stage);});
document.addEventListener('pointerdown',e=>{const node=e.target.closest('[data-node]');if(!node)return;const n=state.design.nodes.find(x=>x.id===node.dataset.node),board=$('#sketch-board');if(!n||!board)return;selected=n.id;document.querySelectorAll('[data-node]').forEach(x=>x.classList.toggle('selected',x.dataset.node===selected));$('#inspector').innerHTML=inspector();drag={id:n.id,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y,rect:board.getBoundingClientRect(),before:JSON.stringify(state.design.nodes)};board.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!drag)return;const n=state.design.nodes.find(x=>x.id===drag.id);n.x=drag.x+(e.clientX-drag.startX)/drag.rect.width*100;n.y=drag.y+(e.clientY-drag.startY)/drag.rect.height*100;clampNode(n);const el=[...document.querySelectorAll('[data-node]')].find(x=>x.dataset.node===n.id);el.style.left=n.x+'%';el.style.top=n.y+'%';});
function endDrag(){if(!drag)return;if(JSON.stringify(state.design.nodes)!==drag.before){undo.push(drag.before);if(undo.length>20)undo.shift();const b=document.querySelector('[data-act="undo"]');if(b)b.disabled=false;}drag=null;save();const b=document.querySelector('[data-act="undo"]');if(b)b.disabled=!undo.length;}
document.addEventListener('pointerup',endDrag);document.addEventListener('pointercancel',endDrag);
document.addEventListener('focusin',e=>{if(e.target.dataset.nodeLabel){rememberNodes();const b=document.querySelector('[data-act="undo"]');if(b)b.disabled=false;return;}if(e.target.dataset.node){selected=e.target.dataset.node;document.querySelectorAll('[data-node]').forEach(x=>x.classList.toggle('selected',x.dataset.node===selected));$('#inspector').innerHTML=inspector();}});
document.addEventListener('keydown',e=>{if(!e.target.dataset.node)return;const n=state.design.nodes.find(x=>x.id===e.target.dataset.node),step=e.shiftKey?5:1;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();rememberNodes();if(e.key==='ArrowLeft')n.x-=step;if(e.key==='ArrowRight')n.x+=step;if(e.key==='ArrowUp')n.y-=step;if(e.key==='ArrowDown')n.y+=step;clampNode(n);e.target.style.left=n.x+'%';e.target.style.top=n.y+'%';save();}else if(e.key==='Delete'){e.preventDefault();handleAction('delete-node',e.target);}});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(state.joined&&C.stages.some(x=>x[0]===id)&&id!==state.stage){state.stage=id;save();render(true);}});
if(new URLSearchParams(location.search).get('report')==='1'){let image='';try{image=sessionStorage.getItem(C.KEY+'-sketch')||'';}catch(e){}window.LessonReport.show(state,image,new URLSearchParams(location.search).get('print')==='1');}else{const id=location.hash.slice(1);if(state.joined&&C.stages.some(x=>x[0]===id))state.stage=id;render();}
})();
